insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-pe-270', 'chemistry-classification-of-elements-and-periodicity-in-properties', 'chemistry', 'Effective nuclear charge felt by the outermost electron', '["falls across a period","increases across a period","is zero for all metals","equals the mass number"]'::jsonb, 1, 'Electrons are added to the same shell, which screens poorly, so Zeff climbs left to right.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'easy', 'periodic-trends-general') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
