insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-pe-271', 'chemistry-classification-of-elements-and-periodicity-in-properties', 'chemistry', 'Down a group, the increase in shielding and the addition of shells outweigh the rise in nuclear charge, so', '["atomic size shrinks","atomic size grows","IE rises sharply","all elements become noble gases"]'::jsonb, 1, 'The net result is a larger, more loosely held valence electron in the heavier congener.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'easy', 'periodic-trends-general') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
