insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-pe-283', 'chemistry-classification-of-elements-and-periodicity-in-properties', 'chemistry', 'Oxygen is smaller than nitrogen, which would suggest a higher IE for O, yet IE of O is lower than that of N because', '["oxygen has a half-filled 2p³ set","the paired 2p⁴ electron of oxygen is easier to remove","nitrogen has the larger nuclear charge","oxygen lacks a 2s pair"]'::jsonb, 1, 'The size trend and the pairing-repulsion trend oppose each other; pairing wins, so IE(N) > IE(O).', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'hard', 'periodic-trends-general') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
